SELECT m.formula
FROM material_entry m
LIMIT 10000;

SELECT
  COUNT(*) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Sc|Ti|V|Cr|Mn|Fe|Co|Ni|Cu|Zn)(-|$)'
  ) AS transition_3d_count,
  AVG(ps.energy_above_hull) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Sc|Ti|V|Cr|Mn|Fe|Co|Ni|Cu|Zn)(-|$)'
  ) AS transition_3d_avg_energy_above_hull,
  COUNT(*) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Sc|Ti|V|Cr|Mn|Fe|Co|Ni|Cu|Zn)(-|$)'
      AND ps.is_stable = TRUE
  ) * 100.0 / NULLIF(
    COUNT(*) FILTER (
      WHERE m.chemical_system ~ '(^|-)(Sc|Ti|V|Cr|Mn|Fe|Co|Ni|Cu|Zn)(-|$)'
    ),
    0
  ) AS transition_3d_stable_percentage,
  AVG(ps.formation_energy_per_atom) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Sc|Ti|V|Cr|Mn|Fe|Co|Ni|Cu|Zn)(-|$)'
  ) AS transition_3d_avg_formation_energy_per_atom,
  COUNT(*) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Y|Zr|Nb|Mo|Tc|Ru|Rh|Pd|Ag|Cd|Hf|Ta|W|Re|Os|Ir|Pt|Au|Hg)(-|$)'
  ) AS transition_4d_5d_count,
  AVG(ps.energy_above_hull) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Y|Zr|Nb|Mo|Tc|Ru|Rh|Pd|Ag|Cd|Hf|Ta|W|Re|Os|Ir|Pt|Au|Hg)(-|$)'
  ) AS transition_4d_5d_avg_energy_above_hull,
  COUNT(*) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Y|Zr|Nb|Mo|Tc|Ru|Rh|Pd|Ag|Cd|Hf|Ta|W|Re|Os|Ir|Pt|Au|Hg)(-|$)'
      AND ps.is_stable = TRUE
  ) * 100.0 / NULLIF(
    COUNT(*) FILTER (
      WHERE m.chemical_system ~ '(^|-)(Y|Zr|Nb|Mo|Tc|Ru|Rh|Pd|Ag|Cd|Hf|Ta|W|Re|Os|Ir|Pt|Au|Hg)(-|$)'
    ),
    0
  ) AS transition_4d_5d_stable_percentage,
  AVG(ps.formation_energy_per_atom) FILTER (
    WHERE m.chemical_system ~ '(^|-)(Y|Zr|Nb|Mo|Tc|Ru|Rh|Pd|Ag|Cd|Hf|Ta|W|Re|Os|Ir|Pt|Au|Hg)(-|$)'
  ) AS transition_4d_5d_avg_formation_energy_per_atom
FROM material_entry m
JOIN phase_stability ps ON ps.entry_id = m.entry_id
WHERE m.chemical_system ~ '(^|-)(Sc|Ti|V|Cr|Mn|Fe|Co|Ni|Cu|Zn|Y|Zr|Nb|Mo|Tc|Ru|Rh|Pd|Ag|Cd|Hf|Ta|W|Re|Os|Ir|Pt|Au|Hg)(-|$)'
LIMIT 10000;
